"""Late enforcement. Generated by tools/generate_overlays.py from
tools/late_results/actions.json; do not edit.

account.risk_changed only wakes the handler. handle_risk_change verifies the
delivery, reads the account's current risk (GET /v1/accounts/{account_id}),
asks your get_account_state where the account is in your own flow, and takes
the actions the table names for that state and the decision of its flow:

    onboarding   account_creation allow         activate
    onboarding   account_creation review/block  fail_onboarding, revoke_sessions
    provisional  account_creation allow         activate
    provisional  account_creation review/block  reject_activation, revoke_sessions
    active       login review                   revoke_sessions
    active       login block                    restrict, revoke_sessions
    restricted   login allow                    unrestrict, when flows["login"].reinstate

Every action, or none, is recorded with accounts.record_enforcement at the
risk_version read, and a refused action is recorded as failed and raised. No
action deletes a user. The same table and vectors
(tests/fixtures/late-results-vectors.json) run in every SDK.
"""

from __future__ import annotations

import json
import math
import re
import time
from dataclasses import dataclass, field
from typing import Any, Callable, Dict, List, Mapping, Optional, Sequence, Union
from urllib.parse import quote

import httpx

from .errors import NotFoundError
from .webhook_verification import DEFAULT_TOLERANCE_SECONDS, Headers, construct_event

__all__ = [
    "AccountStateAnswer",
    "ActionProvider",
    "Enforced",
    "EnforcementResult",
    "FlowPolicy",
    "ProviderActionError",
    "custom_provider",
    "enforce_account",
    "handle_risk_change",
    "identity_provider",
]

_TABLE: Dict[str, Any] = json.loads(r'''{"lifecycle":{"onboarding":{"flow":"account_creation","on":{"allow":["activate"],"review":["fail_onboarding","revoke_sessions"],"block":["fail_onboarding","revoke_sessions"]}},"provisional":{"flow":"account_creation","on":{"allow":["activate"],"review":["reject_activation","revoke_sessions"],"block":["reject_activation","revoke_sessions"]}},"active":{"flow":"login","on":{"review":["revoke_sessions"],"block":["restrict","revoke_sessions"]}},"restricted":{"flow":"login","on":{},"reinstate":{"allow":["unrestrict"]}},"rejected":{"flow":"account_creation","on":{}}},"providers":{"clerk":{"base_url":"https://api.clerk.com/v1","actions":{"fail_onboarding":[{"call":{"method":"POST","path":"/users/{user}/ban"}}],"reject_activation":[{"call":{"method":"POST","path":"/users/{user}/ban"}}],"activate":[],"restrict":[{"call":{"method":"POST","path":"/users/{user}/ban"}}],"unrestrict":[{"call":{"method":"POST","path":"/users/{user}/unban"}}],"revoke_sessions":[{"each":{"list":{"method":"GET","path":"/sessions","query":{"user_id":"{user}","status":"active","limit":"100"}},"page":{"kind":"offset","param":"offset","size":100},"where":{"status":"active"}},"call":{"method":"POST","path":"/sessions/{item}/revoke"}}]}},"workos":{"base_url":"https://api.workos.com","actions":{"fail_onboarding":[{"call":{"method":"PUT","path":"/user_management/users/{user}","body":{"metadata":{"noresponse_state":"onboarding_failed"}}}}],"reject_activation":[{"call":{"method":"PUT","path":"/user_management/users/{user}","body":{"metadata":{"noresponse_state":"activation_rejected"}}}}],"activate":[],"restrict":[{"call":{"method":"PUT","path":"/user_management/users/{user}","body":{"metadata":{"noresponse_state":"restricted"}}}}],"unrestrict":[{"call":{"method":"PUT","path":"/user_management/users/{user}","body":{"metadata":{"noresponse_state":null}}}}],"revoke_sessions":[{"each":{"list":{"method":"GET","path":"/user_management/users/{user}/sessions","query":{"limit":"100"}},"page":{"kind":"cursor","param":"after","next":["list_metadata","after"]},"where":{"status":"active"}},"call":{"method":"POST","path":"/user_management/sessions/revoke","body":{"session_id":"{item}"}}}]}},"auth0":{"base_url":"https://{domain}/api/v2","actions":{"fail_onboarding":[{"call":{"method":"PATCH","path":"/users/{user}","body":{"blocked":true}}}],"reject_activation":[{"call":{"method":"PATCH","path":"/users/{user}","body":{"blocked":true}}}],"activate":[],"restrict":[{"call":{"method":"PATCH","path":"/users/{user}","body":{"blocked":true}}}],"unrestrict":[{"call":{"method":"PATCH","path":"/users/{user}","body":{"blocked":false}}}],"revoke_sessions":[{"call":{"method":"DELETE","path":"/users/{user}/sessions"},"fallback":{"status":403,"code":"feature_not_enabled","reports":"restrict","steps":[{"call":{"method":"PATCH","path":"/users/{user}","body":{"blocked":true}}}]}},{"call":{"method":"DELETE","path":"/users/{user}/refresh-tokens"},"fallback":{"status":403,"code":"feature_not_enabled","steps":[{"each":{"list":{"method":"GET","path":"/device-credentials","query":{"user_id":"{user}","type":"refresh_token","per_page":"100"}},"page":{"kind":"index","param":"page","size":100}},"call":{"method":"DELETE","path":"/device-credentials/{item}"}},{"each":{"list":{"method":"GET","path":"/device-credentials","query":{"user_id":"{user}","type":"rotating_refresh_token","per_page":"100"}},"page":{"kind":"index","param":"page","size":100}},"call":{"method":"DELETE","path":"/device-credentials/{item}"}}]}}]}}},"limits":{"retries":4,"budget_ms":3000,"backoff_ms":250,"max_pages":100}}''')
_LIMITS = _TABLE["limits"]
_ACTIONS = frozenset(next(iter(_TABLE["providers"].values()))["actions"])

# The states of an account in your flow: onboarding, provisional, active, restricted, rejected.
AccountState = str
# An action a provider runs: revoke_sessions, restrict, unrestrict, fail_onboarding, reject_activation or activate.
ProviderAction = str


@dataclass(frozen=True)
class AccountStateAnswer:
    """Where the account is in your flow, from get_account_state."""

    state: AccountState
    # The provider's user id. Defaults to the account id, as when you assess with the provider's user id.
    user_id: Optional[str] = None
    # The risk_version you last enforced (a result's risk_version that you stored). An account at or below it is skipped.
    enforced_risk_version: Optional[int] = None


@dataclass(frozen=True)
class FlowPolicy:
    # Lift a restriction once the flow's decision is allow again. Off by default.
    reinstate: bool = False


@dataclass(frozen=True)
class Enforced:
    flow: str
    action: str
    status: str
    error_code: Optional[str] = None


@dataclass(frozen=True)
class EnforcementResult:
    """What was done. skipped says why nothing was: not_actionable (not account.risk_changed, or a test
    event), account_gone (erased), unknown_user (get_account_state returned None) or already_enforced."""

    # The verified event, from handle_risk_change. Answer an endpoint.verification with its challenge.
    event: Any = None
    account: Any = None
    state: Optional[AccountState] = None
    # The risk_version acted on. Store it and return it as enforced_risk_version.
    risk_version: Optional[int] = None
    skipped: Optional[str] = None
    # What was recorded, in order.
    enforcements: List[Enforced] = field(default_factory=list)


class ProviderActionError(Exception):
    """The provider refused an action or could not be reached (status 0). Answer the webhook with a 5xx so it is delivered again."""

    def __init__(self, provider: str, status: int, message: str, code: Optional[str] = None) -> None:
        super().__init__(message)
        self.provider = provider
        self.status = status
        # The provider's error code, such as Auth0's errorCode "insufficient_scope", when it sent one.
        self.code = code


class ActionProvider:
    """Runs one action in an identity provider. Build one with identity_provider or custom_provider."""

    name: str

    def run(self, action: ProviderAction, user_id: str) -> List[ProviderAction]:
        """Take the action and return any other action that had to run with it (Auth0 restricts to end a session)."""
        raise NotImplementedError


GetAccountState = Callable[[Any], Optional[AccountStateAnswer]]


def handle_risk_change(
    client: Any,
    payload: Union[bytes, str],
    headers: Headers,
    secrets: Mapping[str, str],
    *,
    provider: ActionProvider,
    get_account_state: GetAccountState,
    flows: Optional[Mapping[str, FlowPolicy]] = None,
    tolerance_seconds: int = DEFAULT_TOLERANCE_SECONDS,
    now: Optional[float] = None,
) -> EnforcementResult:
    """Verify an account.risk_changed delivery and enforce the account's current risk.

    A delivery that fails verification raises WebhookVerificationError before
    anything is read; any other event, and a test event, does nothing.
    """
    event = construct_event(payload, headers, secrets, tolerance_seconds=tolerance_seconds, now=now)
    if event.type != "account.risk_changed" or getattr(event, "test", None) is True:
        return EnforcementResult(event=event, skipped="not_actionable")
    try:
        account = client.accounts.get(event.data.account.id)
    except NotFoundError:
        return EnforcementResult(event=event, skipped="account_gone")
    result = enforce_account(client, account, provider=provider, get_account_state=get_account_state, flows=flows)
    return EnforcementResult(event, result.account, result.state, result.risk_version, result.skipped, result.enforcements)


def _text(value: Any) -> str:
    return str(getattr(value, "value", value))


def enforce_account(
    client: Any,
    account: Any,
    *,
    provider: ActionProvider,
    get_account_state: GetAccountState,
    flows: Optional[Mapping[str, FlowPolicy]] = None,
) -> EnforcementResult:
    """Enforce one account as read: the account a handler fetched, or one from
    accounts.list_changed(unenforced=True) when catching up."""
    answer = get_account_state(account)
    if answer is None:
        return EnforcementResult(account=account, skipped="unknown_user")
    state = answer.state
    rule = _TABLE["lifecycle"].get(state)
    if rule is None:
        raise ValueError(f"unknown account state {state!r}")
    risk_version = account.risk_version
    if answer.enforced_risk_version is not None and risk_version <= answer.enforced_risk_version:
        return EnforcementResult(account=account, state=state, risk_version=risk_version, skipped="already_enforced")
    flow = rule["flow"]
    decision = _text(getattr(account.decisions_by_flow, flow))
    policy = (flows or {}).get(flow) or FlowPolicy()
    actions = rule["on"].get(decision)
    if actions is None and policy.reinstate:
        actions = rule.get("reinstate", {}).get(decision)
    enforcements: List[Enforced] = []

    def record(action: str, status: str, error_code: Optional[str] = None) -> None:
        client.accounts.record_enforcement(
            account.id,
            risk_version=risk_version,
            flow=flow,
            action=action,
            state_before=state,
            status=status,
            provider=provider.name,
            error_code=error_code,
        )
        enforcements.append(Enforced(flow, action, status, error_code))

    if not actions:
        # A decision that needs nothing, allow too, still counts as handled, so the account leaves the unenforced feed.
        record("none", "applied")
        return EnforcementResult(account=account, state=state, risk_version=risk_version, enforcements=enforcements)
    recorded = set()
    for action in actions:
        try:
            also_ran = provider.run(action, answer.user_id or account.id)
        except Exception as error:
            record(action, "failed", _failure_code(provider.name, error))
            raise
        for ran in [*also_ran, action]:
            if ran not in recorded:
                recorded.add(ran)
                record(ran, "applied")
    return EnforcementResult(account=account, state=state, risk_version=risk_version, enforcements=enforcements)


_SLUG = re.compile(r"^[a-z0-9_.-]+$")


def _failure_code(provider: str, error: BaseException) -> str:
    """The error_code of a failed action: the provider's code, else its HTTP status, as <provider>.<code>."""
    code = getattr(error, "code", None)
    status = error.status if isinstance(error, ProviderActionError) else None
    if isinstance(code, str) and _SLUG.match(code.lower()):
        suffix = code.lower()
    elif status == 0:
        suffix = "unreachable"
    elif status is not None:
        suffix = f"http_{status}"
    else:
        suffix = "error"
    return f"{provider}.{suffix}"[:128]


class _Context:
    def __init__(self, name: str, base: str, token: str, http: httpx.Client, user: str) -> None:
        self.name = name
        self.base = base
        self.authorization = f"Bearer {token}"
        self.http = http
        self.user = user
        self.waited_ms = 0.0


class _TableProvider(ActionProvider):
    def __init__(self, name: str, spec: Mapping[str, Any], base: str, token: str, http: httpx.Client) -> None:
        self.name = name
        self._spec = spec
        self._base = base
        self._token = token
        self._http = http

    def run(self, action: ProviderAction, user_id: str) -> List[ProviderAction]:
        if not isinstance(user_id, str) or not user_id:
            raise ValueError("user id must be a non-empty string")
        steps = self._spec["actions"].get(action)
        if steps is None:
            raise ValueError(f"unknown action {action!r}")
        return _run_steps(steps, _Context(self.name, self._base, self._token, self._http, user_id))


def identity_provider(
    name: str,
    *,
    token: str,
    domain: Optional[str] = None,
    base_url: Optional[str] = None,
    http: Optional[httpx.Client] = None,
) -> ActionProvider:
    """Clerk, WorkOS or Auth0, run from the shared action table.

    token is the Clerk secret key, WorkOS API key or Auth0 Management API
    token; domain is the Auth0 tenant domain. Pass http for a proxy or for tests.
    """
    spec = _TABLE["providers"].get(name)
    if spec is None:
        raise ValueError(f"unknown identity provider {name!r}")
    if not token:
        raise ValueError(f"{name} needs token")
    base = base_url or spec["base_url"]
    if "{domain}" in base:
        if not domain:
            raise ValueError(f"{name} needs domain or base_url")
        base = base.replace("{domain}", domain)
    return _TableProvider(name, spec, base.rstrip("/"), token, http or httpx.Client(timeout=10.0))


class _CustomProvider(ActionProvider):
    name = "custom"

    def __init__(self, handlers: Mapping[str, Callable[[str], Optional[Sequence[str]]]]) -> None:
        self._handlers = dict(handlers)

    def run(self, action: ProviderAction, user_id: str) -> List[ProviderAction]:
        handler = self._handlers.get(action)
        if handler is None:
            raise ValueError(f"custom_provider has no {action} handler")
        also_ran = handler(user_id)
        # Only a list of action names counts; any other return value (None, True, a model) is no extra action.
        if not isinstance(also_ran, (list, tuple)):
            return []
        return [action for action in also_ran if action in _ACTIONS]


def custom_provider(handlers: Mapping[str, Callable[[str], Optional[Sequence[str]]]]) -> ActionProvider:
    """Your own user store: one function per action you support, keyed by action. An action without one fails."""
    return _CustomProvider(handlers)


def _run_steps(steps: Sequence[Mapping[str, Any]], ctx: _Context) -> List[ProviderAction]:
    also_ran: List[ProviderAction] = []
    for step in steps:
        if "each" in step:
            for item in _collect(step["each"], ctx):
                _send(step["call"], ctx, item)
            continue
        try:
            _send(step["call"], ctx)
        except ProviderActionError as error:
            fallback = step.get("fallback")
            if not fallback or error.status != fallback["status"] or error.code != fallback["code"]:
                raise
            also_ran += _run_steps(fallback["steps"], ctx)
            if fallback.get("reports"):
                also_ran.append(fallback["reports"])
    return also_ran


def _collect(each: Mapping[str, Any], ctx: _Context) -> List[str]:
    """Every matching item id across the list's pages, collected before any is acted on."""
    listing, page, where = each["list"], each["page"], each.get("where", {})
    ids: List[str] = []
    cursor: Optional[str] = None
    for index in range(_LIMITS["max_pages"]):
        query = dict(listing.get("query", {}))
        if page["kind"] == "offset":
            query[page["param"]] = str(index * page["size"])
        elif page["kind"] == "index":
            query[page["param"]] = str(index)
        elif cursor is not None:
            query[page["param"]] = cursor
        body = _send({**listing, "query": query}, ctx)
        data = body.get("data") if isinstance(body, dict) else None
        items = body if isinstance(body, list) else data if isinstance(data, list) else []
        for item in items:
            if not isinstance(item, dict) or not isinstance(item.get("id"), str) or not item["id"]:
                continue
            if all(item.get(key) == value for key, value in where.items()):
                ids.append(item["id"])
        if page["kind"] == "cursor":
            following: Any = body
            for key in page["next"]:
                following = following.get(key) if isinstance(following, dict) else None
            if not isinstance(following, str) or not following:
                break
            cursor = following
        elif len(items) < page["size"]:
            break
    return ids


def _fill(value: Any, user: str, item: Optional[str]) -> Any:
    if isinstance(value, str):
        return value.replace("{user}", user).replace("{item}", item or "")
    if isinstance(value, list):
        return [_fill(entry, user, item) for entry in value]
    if isinstance(value, dict):
        return {key: _fill(entry, user, item) for key, entry in value.items()}
    return value


def _number(text: Optional[str]) -> Optional[float]:
    try:
        value = float(text.strip()) if text else None
    except ValueError:
        return None
    return value if value is not None and math.isfinite(value) else None


def _rate_limit_wait_ms(headers: httpx.Headers, retry: int) -> float:
    """How long a 429 asks to wait, in milliseconds."""
    after = _number(headers.get("retry-after"))
    if after is not None and after >= 0:
        return after * 1000
    reset = _number(headers.get("x-ratelimit-reset"))
    if reset is not None:
        return max(0.0, reset * 1000 - time.time() * 1000)
    return float(_LIMITS["backoff_ms"] * 2**retry)


def _error_code(text: str) -> Optional[str]:
    """The provider's error code: Auth0's errorCode, WorkOS's code or Clerk's errors[0].code."""
    try:
        body = json.loads(text)
    except ValueError:
        return None
    if not isinstance(body, dict):
        return None
    code = body.get("errorCode") or body.get("code")
    errors = body.get("errors")
    if code is None and isinstance(errors, list) and errors and isinstance(errors[0], dict):
        code = errors[0].get("code")
    return code if isinstance(code, str) and code else None


def _send(request: Mapping[str, Any], ctx: _Context, item: Optional[str] = None) -> Any:
    """One admin API call. A 404 is done (None); a 429 is waited out inside the action's budget; any other failure raises."""
    path = request["path"].replace("{user}", quote(ctx.user, safe="")).replace("{item}", quote(item or "", safe=""))
    params = {key: _fill(value, ctx.user, item) for key, value in request.get("query", {}).items()}
    headers = {"authorization": ctx.authorization, "accept": "application/json"}
    content = None
    if "body" in request:
        content = json.dumps(_fill(request["body"], ctx.user, item)).encode("utf-8")
        headers["content-type"] = "application/json"
    label = f"{ctx.name} {request['method']} {request['path']}"
    retry = 0
    while True:
        try:
            response = ctx.http.request(request["method"], ctx.base + path, params=params or None, headers=headers, content=content)
        except httpx.HTTPError as error:
            raise ProviderActionError(ctx.name, 0, f"{label} failed: {error}") from error
        if response.status_code == 429 and retry < _LIMITS["retries"]:
            wait = _rate_limit_wait_ms(response.headers, retry)
            if ctx.waited_ms + wait <= _LIMITS["budget_ms"]:
                ctx.waited_ms += wait
                time.sleep(wait / 1000)
                retry += 1
                continue
        if response.status_code == 404:
            return None
        if not 200 <= response.status_code < 300:
            raise ProviderActionError(ctx.name, response.status_code, f"{label} answered {response.status_code}", _error_code(response.text))
        if not response.content:
            return None
        try:
            return response.json()
        except ValueError:
            return None
